cd "$INPUT_DIR" && python3 -c "
import openpyxl,glob
import zipfile,re
for f in sorted(glob.glob('*.xlsx')):
    wb=openpyxl.load_workbook(f,data_only=True)
    for ws in wb:
        for row in ws.iter_rows():
            for c in row:
                if isinstance(c.value,str) and re.search(r'customer|client|account name|NHS|top \d', c.value, re.I):
                    print(f,ws.title,c.coordinate,repr(c.value)[:120])
" 2>/dev/null | head -60
echo "=== PPTX ==="
cd "$INPUT_DIR" && for p in *.pptx; do echo "--$p--"; python3 -c "
from pptx import Presentation
import sys
pr=Presentation(sys.argv[1])
for i,s in enumerate(pr.slides,1):
    for sh in s.shapes:
        if sh.has_text_frame:
            t=sh.text_frame.text
            if t.strip(): print(i,'|',t.replace(chr(10),' / ')[:400])
        if sh.has_table:
            for r in sh.table.rows: print(i,'|T|',' ; '.join(c.text for c in r.cells)[:300])
" "$p"; done
